(function attachFamilyPassportGoogleDrive(global){
  "use strict";
  const scope="https://www.googleapis.com/auth/drive.file",allowed=new Set(["application/pdf","image/jpeg","image/png"]);let accessToken="",tokenClient=null,loading=null;
  const config=()=>global.familyPassportGoogleDriveConfig||{};
  function configured(){const c=config();return Boolean(c.clientId&&c.apiKey&&c.appId)}
  function loadScript(src,test){if(test())return Promise.resolve();return new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error("Google library could not load."));document.head.append(s)})}
  async function load(){if(!configured())throw Object.assign(new Error("Google Drive credentials are not configured."),{code:"drive_not_configured"});if(loading)return loading;loading=(async()=>{await loadScript("https://accounts.google.com/gsi/client",()=>Boolean(global.google?.accounts?.oauth2));await loadScript("https://apis.google.com/js/api.js",()=>Boolean(global.gapi));await new Promise((resolve,reject)=>global.gapi.load("picker",{callback:resolve,onerror:()=>reject(new Error("Google Picker could not load."))}));tokenClient=global.google.accounts.oauth2.initTokenClient({client_id:config().clientId,scope,callback:()=>{}})})();return loading}
  async function token(prompt=""){await load();return new Promise((resolve,reject)=>{tokenClient.callback=response=>{if(response.error)return reject(Object.assign(new Error(response.error_description||"Drive permission was not granted."),{code:response.error}));accessToken=response.access_token;resolve(accessToken)};tokenClient.requestAccessToken({prompt})})}
  async function metadata(fileId,currentToken){const fields="id,name,mimeType,size,modifiedTime,version,md5Checksum,webViewLink,trashed,parents";const response=await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?fields=${encodeURIComponent(fields)}&supportsAllDrives=true`,{headers:{authorization:`Bearer ${currentToken}`}});if(response.status===404)return {missing:true,status:"missing"};if(response.status===401||response.status===403)return {inaccessible:true,status:"inaccessible"};const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||"Drive metadata could not be read.");if(body.trashed)return {...body,missing:true,status:"missing"};return body}
  async function bytes(fileId,currentToken){const response=await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`,{headers:{authorization:`Bearer ${currentToken}`}});if(!response.ok)throw new Error("The selected Drive file could not be downloaded.");return response.blob()}
  async function pick(){const current=await token(accessToken?"":"consent");return new Promise((resolve,reject)=>{const view=new global.google.picker.DocsView(global.google.picker.ViewId.DOCS).setSelectFolderEnabled(false).setMimeTypes([...allowed].join(","));const picker=new global.google.picker.PickerBuilder().setAppId(config().appId).setDeveloperKey(config().apiKey).setOAuthToken(current).setOrigin(location.origin).setTitle("Choose one family document").setMaxItems(1).addView(view).setCallback(async data=>{if(data.action===global.google.picker.Action.CANCEL)return reject(Object.assign(new Error("Selection cancelled."),{code:"cancelled"}));if(data.action!==global.google.picker.Action.PICKED)return;try{const id=data.docs?.[0]?.id,meta=await metadata(id,current);if(meta.missing||meta.trashed)throw new Error("The selected file is unavailable.");if(!allowed.has(meta.mimeType))throw new Error("Choose a PDF, JPEG or PNG file.");const size=Number(meta.size||0);if(size<1||size>15*1024*1024)throw new Error("Choose a Drive file smaller than 15 MB.");const blob=await bytes(id,current),file=new File([blob],meta.name,{type:meta.mimeType,lastModified:Date.parse(meta.modifiedTime)});resolve({file,metadata:meta})}catch(error){reject(error)}}).build();picker.setVisible(true)})}
  async function pickFolder(){const current=await token(accessToken?"":"consent");return new Promise((resolve,reject)=>{const view=new global.google.picker.DocsView(global.google.picker.ViewId.FOLDERS).setSelectFolderEnabled(true).setIncludeFolders(true);const picker=new global.google.picker.PickerBuilder().setAppId(config().appId).setDeveloperKey(config().apiKey).setOAuthToken(current).setOrigin(location.origin).setTitle("Choose one folder for Family Documents").setMaxItems(1).addView(view).setCallback(data=>{if(data.action===global.google.picker.Action.CANCEL)return reject(Object.assign(new Error("Selection cancelled."),{code:"cancelled"}));if(data.action!==global.google.picker.Action.PICKED)return;const selected=data.docs?.[0]||{},id=String(selected.id||"").trim(),name=String(selected.name||"Family Documents").trim();if(id.length<10||id.length>200)return reject(new Error("Google did not return a valid folder. Please choose it again."));resolve({id,name:name.slice(0,255),webViewLink:selected.url||`https://drive.google.com/drive/folders/${encodeURIComponent(id)}`})}).build();picker.setVisible(true)})}
  async function createFolder(name){const folderName=String(name||"").trim();if(folderName.length<1||folderName.length>80)throw new Error("Enter a folder name between 1 and 80 characters.");const current=await token(accessToken?"":"consent");const response=await fetch("https://www.googleapis.com/drive/v3/files?fields=id,name,mimeType,webViewLink",{method:"POST",headers:{authorization:`Bearer ${current}`,"content-type":"application/json"},body:JSON.stringify({name:folderName,mimeType:"application/vnd.google-apps.folder"})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||"Google Drive could not create the folder.");return {id:body.id,name:body.name,webViewLink:body.webViewLink||`https://drive.google.com/drive/folders/${encodeURIComponent(body.id)}`}}
  async function upload(file,folderId){if(!allowed.has(file.type)||file.size<1||file.size>5*1024*1024)throw new Error("Choose a JPEG, PNG or PDF smaller than 5 MB.");const current=await token(accessToken?"":"consent");let created=null;try{let response=await fetch("https://www.googleapis.com/drive/v3/files?fields=id,name,mimeType,size,modifiedTime,version,md5Checksum,webViewLink,parents",{method:"POST",headers:{authorization:`Bearer ${current}`,"content-type":"application/json"},body:JSON.stringify({name:file.name,mimeType:file.type,parents:[folderId]})});created=await response.json().catch(()=>({}));if(!response.ok)throw new Error(created.error?.message||"Drive could not create the file.");response=await fetch(`https://www.googleapis.com/upload/drive/v3/files/${encodeURIComponent(created.id)}?uploadType=media&fields=id,name,mimeType,size,modifiedTime,version,md5Checksum,webViewLink,parents`,{method:"PATCH",headers:{authorization:`Bearer ${current}`,"content-type":file.type},body:file});const saved=await response.json().catch(()=>({}));if(!response.ok)throw new Error(saved.error?.message||"Drive could not upload the file.");return saved}catch(error){if(created?.id)await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(created.id)}`,{method:"DELETE",headers:{authorization:`Bearer ${current}`}}).catch(()=>{});throw error}}
  async function removeCreated(fileId){if(!fileId)return;const current=await token("");await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}`,{method:"DELETE",headers:{authorization:`Bearer ${current}`}})}
  async function inspect(fileId){const current=await token("");return metadata(fileId,current)}
  async function open(fileId){const current=await token("");const meta=await metadata(fileId,current);if(meta.missing)return {missing:true,metadata:meta};if(meta.inaccessible)return {inaccessible:true,metadata:meta};if(!allowed.has(meta.mimeType))throw new Error("This Drive file type is no longer supported.");return {missing:false,metadata:meta,blob:await bytes(fileId,current)}}
  function disconnect(){if(accessToken&&global.google?.accounts?.oauth2)global.google.accounts.oauth2.revoke(accessToken,()=>{});accessToken=""}
  global.familyPassportGoogleDrive=Object.freeze({scope,configured,pick,pickFolder,createFolder,upload,removeCreated,inspect,open,disconnect});
})(window);
